        parse_transcript_log(["", "  # comment", "a,1,0", bad_line])


def test_dedupe_transcripts_keeps_last_id_and_sorts_by_day_then_id():
    older_record = {"id": "a", "day": 4, "flagged": True}
    replacement = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    earlier_day = {"id": "z", "day": 1, "flagged": True}
    assert dedupe_transcripts([older_record, same_day, replacement, earlier_day]) == [
        earlier_day, replacement, same_day,
    ]


def test_daily_flag_counts_fills_gaps_and_ignores_out_of_range_days():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,3,1", "f,3,", "g,4,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []


def test_monitor_summary_uses_calendar_days_and_counts_only_nonempty_groups():
    events = parse_transcript_log(["a,1,1", "b,3,1", "c,5,0"])
    groups = {"a": events[:1], "b": events[1:], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_breaks_ties_by_name_and_excludes_empty_groups():
